"""Abstract interface for memory systems."""

import hashlib
import json
import re
import threading
from abc import ABC, abstractmethod
from typing import Any

from .llm import LLMCallable


def extract_json_field(text: str, field: str, default: str = "") -> str:
    """Helper function to extract a field from JSON in LLM response."""
    # Try direct parse
    try:
        data = json.loads(text)
        if isinstance(data, dict):
            return str(data.get(field, default))
    except json.JSONDecodeError:
        pass

    # Try code blocks: ```json ... ``` or ``` ... ```
    for match in re.finditer(r"```(?:json)?\s*([\s\S]*?)\s*```", text):
        try:
            data = json.loads(match.group(1))
            if isinstance(data, dict):
                return str(data.get(field, default))
        except json.JSONDecodeError:
            pass

    # Find balanced braces and try parsing
    for start in range(len(text)):
        if text[start] != "{":
            continue
        depth, pos, in_str = 1, start + 1, False
        while pos < len(text) and depth > 0:
            c = text[pos]
            if c == '"' and (pos == 0 or text[pos - 1] != "\\"):
                in_str = not in_str
            elif not in_str:
                depth += 1 if c == "{" else (-1 if c == "}" else 0)
            pos += 1
        if depth == 0:
            candidate = text[start:pos]
            candidate = re.sub(
                r",\s*([\]}])", r"\1", candidate
            )  # Remove trailing commas
            try:
                data = json.loads(candidate)
                if isinstance(data, dict):
                    return str(data.get(field, default))
            except json.JSONDecodeError:
                pass

    # Regex fallback
    match = re.findall(rf'"{field}"\s*:\s*"([^"]*)"', text)
    return match[-1] if match else default


class MemorySystem(ABC):
    """Memory system interface for online and offline learning.

    Args:
        llm: Callable that takes a prompt string and returns a response string.
    """

    def __init__(self, llm: LLMCallable):
        self._llm = llm
        self._prompt_local = threading.local()

    def call_llm(self, prompt: str) -> str:
        """Call the LLM with a prompt. Tracks last prompt length/hash per thread."""
        self._prompt_local.last_prompt_len = len(prompt)
        self._prompt_local.last_prompt_hash = hashlib.md5(prompt.encode()).hexdigest()[
            :8
        ]
        self._prompt_local.last_prompt_text = prompt
        return self._llm(prompt)

    def get_last_prompt_info(self) -> dict[str, Any]:
        """Return length, hash, and full text of the last prompt sent via call_llm (thread-local)."""
        return {
            "prompt_len": getattr(self._prompt_local, "last_prompt_len", None),
            "prompt_hash": getattr(self._prompt_local, "last_prompt_hash", None),
            "prompt_text": getattr(self._prompt_local, "last_prompt_text", None),
        }

    @abstractmethod
    def predict(self, input: str) -> tuple[str, dict[str, Any]]:
        """Generate prediction BEFORE seeing ground truth. Returns (answer, metadata)."""
        pass

    @abstractmethod
    def learn_from_batch(self, batch_results: list[dict[str, Any]]) -> None:
        """Learn from a batch of evaluation results.

        Args:
            batch_results: List of dicts, each containing:
                - input: str
                - prediction: str
                - ground_truth: str
                - was_correct: bool
                - metadata: dict (optional)

        This is called AFTER all predictions in the batch are complete.
        The memory system can analyze patterns across the batch.
        """
        pass

    def get_context_length(self) -> int:
        """Return the character length of context actually injected per query.

        Override in subclasses where the injected context differs from stored state
        (e.g., fewshot memories that store all examples but only inject N).
        """
        return len(self.get_state())

    @abstractmethod
    def get_state(self) -> str:
        """Return serializable state for checkpointing."""
        pass

    @abstractmethod
    def set_state(self, state: str) -> None:
        """Restore state from serialized representation."""
        pass
"""Few-Shot Memory - baseline using all training examples as demonstrations.

Accumulates (raw_question, ground_truth) pairs during training, uses them as
few-shot context at test time. Uses raw questions (not full preprocessed prompts)
to avoid repeating task context per example — matching MCE reproduce behavior.

Variant:
- FewShotAll: Up to 9999 examples
Uses a global max_chars=50000 cap (matching MCE reproduce).
"""

import hashlib
import json
import random
from typing import Any

from ..llm import LLMCallable
from ..memory_system import MemorySystem, extract_json_field

PROMPT_TEMPLATE = """Solve the problem below based on the examples provided.

{examples_section}

**Problem:**
{input}

**Instructions:**
- Follow the patterns shown in the examples above
- Respond in JSON format

{{"reasoning": "[your reasoning]", "final_answer": "[your answer]"}}"""

MAX_CHARS = 30000


def _seed_for_input(input: str) -> int:
    """Return a stable per-input seed across Python processes."""
    return int.from_bytes(hashlib.sha256(input.encode()).digest()[:8], "big")


class FewShotMemory(MemorySystem):
    """Few-shot baseline - accumulate all examples, use as demonstrations."""

    def __init__(
        self,
        llm: LLMCallable,
        max_examples: int = 50,
    ):
        super().__init__(llm)
        self.max_examples = max_examples
        self.examples: list[dict[str, str]] = []

    def _format_examples_section(self, seed: int | None = None) -> str:
        """Format examples as few-shot demonstrations, respecting global char limit.

        Uses raw_question (short Q/A) when available to avoid repeating task
        context per example. Falls back to full input for non-MCE datasets.

        Args:
            seed: If provided, randomly sample max_examples and shuffle order.
                  Each eval instance should pass a different seed for diversity.
        """
        if not self.examples:
            return ""

        if seed is not None and len(self.examples) > self.max_examples:
            rng = random.Random(seed)
            to_use = rng.sample(self.examples, self.max_examples)
        else:
            to_use = self.examples[-self.max_examples :]
            if seed is not None:
                rng = random.Random(seed)
                to_use = list(to_use)
                rng.shuffle(to_use)

        parts = []
        total_chars = 0
        for ex in to_use:
            # Use raw_question for demos (avoids repeating task context per example)
            question = ex.get("raw_question", ex["input"])
            part = f"Q: {question}\nA: {ex['target']}"
            if total_chars + len(part) > MAX_CHARS:
                break
            parts.append(part)
            total_chars += len(part) + 2  # \n\n separator

        return "\n\n".join(parts)

    def predict(self, input: str) -> tuple[str, dict[str, Any]]:
        """Generate prediction using accumulated few-shot examples."""
        seed = _seed_for_input(input)
        examples_section = self._format_examples_section(seed=seed)
        prompt = PROMPT_TEMPLATE.format(
            examples_section=examples_section,
            input=input,
        )

        response = self.call_llm(prompt)
        answer = extract_json_field(response, "final_answer")

        return answer, {
            "full_response": response,
            "num_examples": len(self.examples),
        }

    def learn_from_batch(self, batch_results: list[dict[str, Any]]) -> None:
        """Accumulate all examples with ground truth labels."""
        for r in batch_results:
            ex = {"input": r["input"], "target": r["ground_truth"]}
            if "raw_question" in r:
                ex["raw_question"] = r["raw_question"]
            self.examples.append(ex)

    def get_context_length(self) -> int:
        """Return length of the examples section actually injected per query."""
        return len(self._format_examples_section())

    def get_state(self) -> str:
        """Serialize memory state."""
        return json.dumps({"examples": self.examples}, indent=2)

    def set_state(self, state: str) -> None:
        """Restore memory state from JSON."""
        data = json.loads(state)
        self.examples = data.get("examples", [])
"""Represent learned labels with compact discriminative terms and medoid examples."""

import json
import math
import re
from collections import Counter, defaultdict
from typing import Any

from ..llm import LLMCallable
from ..memory_system import MemorySystem, extract_json_field


PROMPT = """Choose the label that best fits the problem. The profiles are compact summaries
of labeled examples; use the example wording and distinctive features to compare categories.
Use the exact spelling of one learned label, follow any answer format explicitly requested
in the problem, and do not add qualifications.

Learned label profiles:
{profiles}

Problem:
{input}

Return JSON only: {{"reasoning": "brief rationale", "final_answer": "exact label"}}"""

_STOP = {
    "a", "an", "and", "are", "as", "at", "be", "been", "being", "but",
    "by", "for", "from", "had", "has", "have", "he", "her", "his", "i",
    "in", "into", "is", "it", "its", "me", "my", "of", "on", "or",
    "our", "she", "that", "the", "their", "them", "there", "they", "this",
    "to", "up", "was", "we", "were", "when", "which", "with", "you", "your",
}


def _trim_shared_prefix(texts: list[str]) -> str:
    if not texts:
        return ""
    prefix = texts[0]
    for text in texts[1:]:
        limit = min(len(prefix), len(text))
        pos = 0
        while pos < limit and prefix[pos] == text[pos]:
            pos += 1
        prefix = prefix[:pos]
    return prefix if len(prefix) >= 40 else ""


def _body(text: str, prefix: str) -> str:
    return text[len(prefix) :].strip() if prefix and text.startswith(prefix) else text.strip()


def _tokens(text: str) -> list[str]:
    return [token for token in re.findall(r"[a-z0-9]+", text.lower()) if len(token) > 1 and token not in _STOP]


def _cosine(left: list[str], right: list[str], idf: dict[str, float]) -> float:
    a, b = Counter(left), Counter(right)
    common = set(a) & set(b)
    dot = sum(a[t] * b[t] * idf.get(t, 1.0) ** 2 for t in common)
    na = math.sqrt(sum(v * v * idf.get(t, 1.0) ** 2 for t, v in a.items()))
    nb = math.sqrt(sum(v * v * idf.get(t, 1.0) ** 2 for t, v in b.items()))
    return dot / (na * nb) if na and nb else 0.0


class ClassSignatureMemory(MemorySystem):
    """Compress examples into label signatures and one representative instance each."""

    def __init__(self, llm: LLMCallable):
        super().__init__(llm)
        self.examples: list[dict[str, str]] = []

    def _profiles(self) -> list[str]:
        if not self.examples:
            return []
        inputs = [ex.get("raw_question", ex["input"]) for ex in self.examples]
        prefix = _trim_shared_prefix(inputs)
        docs = [_tokens(_body(text, prefix)) for text in inputs]
        labels: dict[str, list[int]] = defaultdict(list)
        for index, ex in enumerate(self.examples):
            labels[ex["target"]].append(index)

        df = Counter(token for doc in docs for token in set(doc))
        total = len(docs)
        idf = {token: math.log((total + 1) / (freq + 1)) + 0.2 for token, freq in df.items()}
        global_counts = Counter(token for doc in docs for token in set(doc))
        profiles = []
        for label in sorted(labels):
            indexes = labels[label]
            in_count = Counter(token for idx in indexes for token in set(docs[idx]))
            outside = max(0, total - len(indexes))
            in_size = len(indexes)
            terms = []
            for token, count in in_count.items():
                other_count = global_counts[token] - count
                p_in = (count + 0.5) / (in_size + 1.0)
                p_out = (other_count + 0.5) / (outside + 1.0)
                contrast = math.log(p_in / (1 - p_in)) - math.log(p_out / (1 - p_out))
                terms.append((contrast * idf.get(token, 1.0), token))
            signature = ", ".join(token for _, token in sorted(terms, reverse=True)[:5])

            medoid_idx = max(
                indexes,
                key=lambda idx: sum(
                    _cosine(docs[idx], docs[other], idf)
                    for other in indexes
                    if other != idx
                ) / max(1, len(indexes) - 1),
            )
            question = self.examples[medoid_idx].get("raw_question", self.examples[medoid_idx]["input"])
            question = _body(question, prefix).replace("\n", " ").strip()[:260]
            profiles.append(
                f"Label: {label}\nDistinctive terms: {signature or '(none yet)'}\n"
                f"Representative example: {question}"
            )
        return profiles

    def predict(self, input: str) -> tuple[str, dict[str, Any]]:
        profiles = self._profiles()
        response = self.call_llm(PROMPT.format(profiles="\n\n".join(profiles), input=input))
        return extract_json_field(response, "final_answer"), {
            "num_labels": len(profiles),
            "num_examples": len(self.examples),
        }

    def learn_from_batch(self, batch_results: list[dict[str, Any]]) -> None:
        for result in batch_results:
            self.examples.append(
                {
                    "input": result["input"],
                    "raw_question": result.get("raw_question", result["input"]),
                    "target": str(result["ground_truth"]),
                }
            )

    def get_state(self) -> str:
        return json.dumps({"examples": self.examples}, ensure_ascii=False)

    def set_state(self, state: str) -> None:
        self.examples = json.loads(state).get("examples", [])

    def get_context_length(self) -> int:
        return len("\n\n".join(self._profiles()))
"""Use previously incorrect labeled cases as targeted correction demonstrations."""

import hashlib
import json
import math
import re
from collections import Counter
from typing import Any

from ..llm import LLMCallable
from ..memory_system import MemorySystem, extract_json_field


PROMPT = """The following cases record earlier mistakes and their corrected labels.
Treat each correction as authoritative evidence. Compare the current problem with the
closest corrected cases, then give one concise answer using the exact corrected label.
Follow any answer format explicitly requested in the problem, and do not add qualifications.

{corrections}

Problem:
{input}

Return JSON only: {{"reasoning": "brief rationale", "final_answer": "exact label"}}"""

_STOP = {
    "a", "an", "and", "are", "as", "at", "be", "been", "being", "but",
    "by", "for", "from", "had", "has", "have", "he", "her", "his", "i",
    "in", "into", "is", "it", "its", "me", "my", "of", "on", "or",
    "our", "she", "that", "the", "their", "them", "there", "they", "this",
    "to", "up", "was", "we", "were", "when", "which", "with", "you", "your",
}


def _tokens(text: str) -> list[str]:
    return [token for token in re.findall(r"[a-z0-9]+", text.lower()) if len(token) > 1 and token not in _STOP]


def _shared_prefix(texts: list[str]) -> str:
    if not texts:
        return ""
    prefix = texts[0]
    for text in texts[1:]:
        end = min(len(prefix), len(text))
        pos = 0
        while pos < end and prefix[pos] == text[pos]:
            pos += 1
        prefix = prefix[:pos]
    return prefix if len(prefix) >= 40 else ""


def _body(text: str, prefix: str) -> str:
    return text[len(prefix) :].strip() if prefix and text.startswith(prefix) else text.strip()


def _similarity(left: str, right: str, corpus: list[str]) -> float:
    docs = [_tokens(text) for text in corpus]
    df = Counter(token for doc in docs for token in set(doc))
    n = max(1, len(docs))

    def vector(tokens: list[str]) -> dict[str, float]:
        counts = Counter(tokens)
        return {
            token: (1.0 + math.log(freq)) * max(0.12, math.log((n + 1) / (df.get(token, 0) + 1)))
            for token, freq in counts.items()
        }

    a, b = vector(_tokens(left)), vector(_tokens(right))
    na = math.sqrt(sum(value * value for value in a.values()))
    nb = math.sqrt(sum(value * value for value in b.values()))
    if not na or not nb:
        return 0.0
    return sum(value * b.get(token, 0.0) for token, value in a.items()) / (na * nb)


def _short_answer(answer: str) -> str:
    answer = re.sub(r"\[[^\]]+\]", " ", str(answer))
    return " ".join(answer.split())[:160]


class ErrorCorrectionMemory(MemorySystem):
    """Retain only failed predictions, paired with the labels that corrected them."""

    def __init__(self, llm: LLMCallable):
        super().__init__(llm)
        self.corrections: list[dict[str, str]] = []
        self._seen: set[str] = set()
        self.max_corrections = 200
        self.max_retrieved = 5

    def predict(self, input: str) -> tuple[str, dict[str, Any]]:
        corpus = [item["input"] for item in self.corrections]
        prefix = _shared_prefix(corpus + [input]) if corpus else ""
        query = _body(input, prefix)
        ranked = sorted(
            [
                (
                _similarity(query, _body(item["input"], prefix), [_body(text, prefix) for text in corpus]),
                index,
                item,
                )
                for index, item in enumerate(self.corrections)
            ],
            key=lambda row: (row[0], row[1]),
            reverse=True,
        )
        selected = [row[2] for row in ranked[: self.max_retrieved] if row[0] > 0]
        correction_text = "\n\n".join(
            f"Earlier problem: {_body(item['input'], prefix)}\nEarlier wrong answer: {item['prediction']}\n"
            f"Correct label: {item['target']}"
            for item in selected
        )
        if not correction_text:
            correction_text = "No similar corrected cases have been stored yet."
        self._last_context_chars = len(correction_text)
        response = self.call_llm(PROMPT.format(corrections=correction_text, input=input))
        return extract_json_field(response, "final_answer"), {
            "num_corrections": len(self.corrections),
            "num_retrieved": len(selected),
        }

    def learn_from_batch(self, batch_results: list[dict[str, Any]]) -> None:
        for result in batch_results:
            if result.get("was_correct", False):
                continue
            item = {
                "input": result["input"],
                "prediction": _short_answer(result.get("prediction", "")),
                "target": str(result["ground_truth"]),
            }
            key = hashlib.sha256(
                json.dumps(item, sort_keys=True, ensure_ascii=False).encode("utf-8")
            ).hexdigest()
            if key not in self._seen:
                self._seen.add(key)
                self.corrections.append(item)
        self.corrections = self.corrections[-self.max_corrections :]
        self._seen = {
            hashlib.sha256(json.dumps(item, sort_keys=True, ensure_ascii=False).encode("utf-8")).hexdigest()
            for item in self.corrections
        }

    def get_state(self) -> str:
        return json.dumps({"corrections": self.corrections}, ensure_ascii=False)

    def set_state(self, state: str) -> None:
        self.corrections = json.loads(state).get("corrections", [])[-self.max_corrections :]
        self._seen = {
            hashlib.sha256(json.dumps(item, sort_keys=True, ensure_ascii=False).encode("utf-8")).hexdigest()
            for item in self.corrections
        }

    def get_context_length(self) -> int:
        return getattr(self, "_last_context_chars", 0)
"""Retrieve a compact, diverse set of labeled examples by lexical similarity."""

import json
import math
import re
from collections import Counter
from typing import Any

from ..llm import LLMCallable
from ..memory_system import MemorySystem, extract_json_field


PROMPT = """Use the labeled examples as demonstrations of the task's categories.
Prefer the examples whose problem details are most similar to the current problem.
Return one concise answer using the exact label wording from the examples or input.
Follow any answer format explicitly requested in the problem, and do not add qualifications.

{examples}

Problem:
{input}

Return JSON only: {{"reasoning": "brief rationale", "final_answer": "exact label"}}"""

_STOP = {
    "a", "an", "and", "are", "as", "at", "be", "been", "being", "but",
    "by", "for", "from", "had", "has", "have", "he", "her", "his", "i",
    "in", "into", "is", "it", "its", "me", "my", "of", "on", "or",
    "our", "she", "that", "the", "their", "them", "there", "they", "this",
    "to", "up", "was", "we", "were", "when", "which", "with", "you", "your",
}


def _common_edges(texts: list[str]) -> tuple[str, str]:
    """Find long literal wrappers shared by inputs so they do not dominate retrieval."""
    if not texts:
        return "", ""
    prefix = texts[0]
    for text in texts[1:]:
        limit = min(len(prefix), len(text))
        idx = 0
        while idx < limit and prefix[idx] == text[idx]:
            idx += 1
        prefix = prefix[:idx]
        if not prefix:
            break
    suffix = texts[0]
    for text in texts[1:]:
        limit = min(len(suffix), len(text))
        idx = 0
        while idx < limit and suffix[-idx - 1] == text[-idx - 1]:
            idx += 1
        suffix = suffix[len(suffix) - idx :] if idx else ""
        if not suffix:
            break
    return (prefix if len(prefix) >= 40 else "", suffix if len(suffix) >= 40 else "")


def _body(text: str, edges: tuple[str, str]) -> str:
    prefix, suffix = edges
    if prefix and text.startswith(prefix):
        text = text[len(prefix) :]
    if suffix and text.endswith(suffix):
        text = text[: -len(suffix)]
    return text.strip()


def _tokens(text: str) -> list[str]:
    return [w for w in re.findall(r"[a-z0-9]+", text.lower()) if len(w) > 1 and w not in _STOP]


def _vectorize(tokens: list[str], df: Counter[str], count: int) -> dict[str, float]:
    tf = Counter(tokens)
    result = {}
    for token, frequency in tf.items():
        # A small floor keeps common words usable while strongly favoring rarer details.
        idf = max(0.12, math.log((count + 1) / (df.get(token, 0) + 1)))
        result[token] = (1.0 + math.log(frequency)) * idf
    return result


def _cosine(a: dict[str, float], b: dict[str, float]) -> float:
    norm_a = math.sqrt(sum(value * value for value in a.values()))
    norm_b = math.sqrt(sum(value * value for value in b.values()))
    if not norm_a or not norm_b:
        return 0.0
    dot = sum(value * b.get(token, 0.0) for token, value in a.items())
    return dot / (norm_a * norm_b)


class IDFRetrievalMemory(MemorySystem):
    """Keep a small number of high-overlap demonstrations with label diversity."""

    def __init__(self, llm: LLMCallable):
        super().__init__(llm)
        self.examples: list[dict[str, str]] = []
        self.max_examples = 10
